import type { AnalyticsPoint } from '@/lib/vendor/analytics'

export function AnalyticsChart({ points }: { points: AnalyticsPoint[] }) { if (!points.length) return <div className="analytics-chart-empty"><strong>Performance charts are not connected yet.</strong><span>Views, clicks, enquiries, and conversion trends will appear after vendor-scoped event aggregation is available.</span></div>; const max = Math.max(...points.map((point) => Math.max(point.views, point.clicks, point.enquiries)), 1); return <div className="analytics-chart" aria-label="Product performance trend">{points.map((point) => <div className="analytics-chart-column" key={point.date}><div className="analytics-chart-bars"><i style={{ height: `${(point.views / max) * 100}%` }} /><b style={{ height: `${(point.clicks / max) * 100}%` }} /></div><small>{point.date}</small></div>)}</div> }